import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { toast, ToastContainer } from "react-toastify";

const DashboardDoctors = () => {
  const navigate = useNavigate();
  const [doctorList, setDoctorList] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalDoctors, setTotalDoctors] = useState(0);
  const [name, setName] = useState("");

  const doctorsPerPage = 8;

  // Confirmation modal states
  const [showModal, setShowModal] = useState(false);
  const [selectedDoctorForToggle, setSelectedDoctorForToggle] = useState(null);
  const [relatedServices, setRelatedServices] = useState([]);
  const [modalLoading, setModalLoading] = useState(false);

  
  const fetchSearchedDoctors = async (query, page = 1) => {
  try {
    const centreId = localStorage.getItem("centreId");
    if (!centreId) return;

    const res = await axios.get(
      `${process.env.REACT_APP_BACKEND_URL}/api/doctors/searchDoctor?query=${query}&centreId=${centreId}&page=${page}&limit=${doctorsPerPage}&dashboard=true`
    );

    setDoctorList(res.data.doctors);
    setCurrentPage(res.data.currentPage);
    setTotalPages(res.data.totalPages);
    setTotalDoctors(res.data.totalDoctors);
  } catch (error) {
    console.error("Error fetching doctors:", error);
    setDoctorList([]);
  }
};

const fetchDoctors = async (page = 1) => {
  const centreId = localStorage.getItem("centreId");
  if (!centreId) return;

  try {
    const response = await axios.get(
      `${process.env.REACT_APP_BACKEND_URL}/api/doctors/centre/${centreId}?page=${page}&limit=${doctorsPerPage}&dashboard=true`
    );

    setDoctorList(response.data.doctors);
    setCurrentPage(response.data.currentPage);
    setTotalPages(response.data.totalPages);
    setTotalDoctors(response.data.totalDoctors);
  } catch (error) {
    console.error("Error fetching doctors:", error);
  }
};

 useEffect(() => {
  const delayDebounce = setTimeout(() => {
    if (name.trim() !== "") {
      fetchSearchedDoctors(name, currentPage);
    } else {
      fetchDoctors(currentPage);
    }
  }, 500);

  return () => clearTimeout(delayDebounce);
}, [name, currentPage]);

// useEffect(() => {
//   fetchDoctors(currentPage);
// }, [currentPage]);

  const handleDelete = async (doctorId) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this doctor?"
    );
    if (!confirmDelete) return;

    try {
      await axios.delete(
        `${process.env.REACT_APP_BACKEND_URL}/api/doctors/${doctorId}`
      );
      toast.success("Doctor deleted successfully!");
      setDoctorList((prev) => prev.filter((doctor) => doctor._id !== doctorId));
    } catch (error) {
      console.error("Failed to delete doctor:", error);
      toast.error("Failed to delete doctor. Please try again.");
    }
  };

  const handleToggleActive = async (id, currentStatus) => {
    try {
      await axios.put(
        `${process.env.REACT_APP_BACKEND_URL}/api/doctors/edit-doctor/${id}`,
        {
          isActive: !currentStatus,
        }
      );
      toast.success("Doctor status updated successfully!");
      setDoctorList((prev) =>
        prev.map((doc) =>
          doc._id === id ? { ...doc, isActive: !currentStatus } : doc
        )
      );
    } catch (error) {
      console.error("Failed to update status:", error);
      toast.error("Failed to update status.");
    }
  };

  const fetchRelatedServices = async (doctorId) => {
    setModalLoading(true);
    try {
      const centreId = localStorage.getItem("centreId");
      if (!centreId) return;

      const response = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/centreService/by-centre/${centreId}`
      );
      const allServices = response.data.services || [];
      
      // Filter services that include this doctor
      const filtered = allServices.filter(service => 
        service.doctors?.some(doc => doc === doctorId || doc._id === doctorId)
      );
      setRelatedServices(filtered);
    } catch (error) {
      console.error("Failed to fetch related services:", error);
      setRelatedServices([]);
    } finally {
      setModalLoading(false);
    }
  };

  const handleToggleClick = (doctor) => {
    const isCurrentlyActive = doctor.isActive !== false;
    if (isCurrentlyActive) {
      setSelectedDoctorForToggle(doctor);
      setShowModal(true);
      fetchRelatedServices(doctor._id);
    } else {
      handleToggleActive(doctor._id, false);
    }
  };

  const handleConfirmDeactivate = async () => {
    if (!selectedDoctorForToggle) return;
    try {
      await handleToggleActive(selectedDoctorForToggle._id, true);
    } finally {
      setShowModal(false);
      setSelectedDoctorForToggle(null);
      setRelatedServices([]);
    }
  };

  const handleCancelDeactivate = () => {
    setShowModal(false);
    setSelectedDoctorForToggle(null);
    setRelatedServices([]);
  };

  const handleEdit = (id) => {
    navigate(`/edit-doctor/${id}`);
  };

  const handlePageChange = (pageNumber) => {
  setCurrentPage(pageNumber);
  window.scrollTo({ top: 0, behavior: "smooth" });
};
  
//   const handlePageChangeWithScroll = (page) => {
//   handlePageChange(page); // your existing page change logic
//   window.scrollTo({ top: 0, behavior: "smooth" }); // scroll to top smoothly
// };

  const renderPagination = () => {
    const pages = [];
    const maxVisible = 4;
    let startPage = Math.max(1, currentPage - Math.floor(maxVisible / 2));
    let endPage = startPage + maxVisible - 1;

    if (endPage > totalPages) {
      endPage = totalPages;
      startPage = Math.max(1, endPage - maxVisible + 1);
    }
 pages.push(
    <li
      key="first"
      className={`page-item ${currentPage === 1 ? " disabled" : ""}`}
    >
      <button
        className="page-link"
        onClick={() => currentPage !== 1 && handlePageChange(1)}
       
      >
        First
      </button>
    </li>
  );


    pages.push(
      <li
        key="prev"
        className={`page-item ${currentPage === 1 ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() => currentPage > 1 && handlePageChange(currentPage - 1)}
        >
          Prev
        </button>
      </li>
    );

    for (let i = startPage; i <= endPage; i++) {
      pages.push(
        <li
          key={i}
          className={`page-item ${currentPage === i ? "active" : ""}`}
        >
          <button className="page-link" onClick={() => handlePageChange(i)}>
             {i}
          </button>
        </li>
      );
    }

    pages.push(
      <li
        key="next"
        className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() =>
            currentPage < totalPages && handlePageChange(currentPage + 1)
          }
        >
          Next
        </button>
      </li>
    );

    pages.push(
      <li
        key="last"
        className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() => handlePageChange(totalPages)}
        >
          Last
        </button>
      </li>
    );

    return pages;
  };

  return (
    <div className="dashboard-body__content">
      <div className="row gy-4">
        <div className="col-12">
          <div className="card common-card border border-gray-five">
            <div className="card-body">
              {/* Header Section */}
              <div className="doctor-header">
                <h4 className="doctor-title">Available Doctors</h4>
                <div className="doctor-actions">
                  <input
                    type="text"
                    className="common-input border-gray-five doctor-search-input"
                    value={name}
                   onChange={(e) => {
  setName(e.target.value);
  setCurrentPage(1);
}}
                    placeholder="Search by name or specialization"
                  />
                  <button
                    className="add-doctor-btn"
                    onClick={() => navigate("/create-doctor")}
                  >
                    Add Doctors
                  </button>
                </div>
              </div>

              <div className="table-responsive">
                <table className="table text-body mt--24">
                  <thead>
                    <tr>
                      <th>SN.</th>
                      <th>Image</th>
                      <th>Name</th>
                      <th>Specialization</th>
                      <th>Qualification</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {doctorList.length > 0 ? (
                     doctorList.map((doc, i) => (
                        <tr key={doc._id}>
                          <td>{(currentPage - 1) * doctorsPerPage + i + 1}</td>
                          <td data-label="Image">
                            <img
                              src={doc.profilePhoto}
                              alt="Doctor Avatar"
                              className="doctor-avatar" loading="lazy"
                            />
                          </td>
                          <td data-label="Name">{doc.name}</td>
                          <td data-label="Specialization">
                            {doc.specialization}
                          </td>
                          <td data-label="Qualification">
                            {doc.qualification?.length > 70
                              ? doc.qualification.slice(0, 70) + "..."
                              : doc.qualification}
                          </td>
                          <td>
                            <button
                              className="edit-btn"
                              onClick={() => handleEdit(doc._id)}
                              style={{ verticalAlign: "middle" }}
                            >
                              Edit
                            </button>
                            <label className="switch" style={{ marginLeft: "10px", display: "inline-block", verticalAlign: "middle" }} title={doc.isActive !== false ? "Active" : "Inactive"}>
                              <input
                                type="checkbox"
                                checked={doc.isActive !== false}
                                onChange={() => handleToggleClick(doc)}
                              />
                              <span className="slider round"></span>
                            </label>
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan="6" className="text-center">
                          No doctors found.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>

              {totalPages > 1 && (
                <div className="flx-between gap-2">
                  <div className="paginate-content flx-align flex-nowrap gap-3">
                    <span className="paginate-content__text fs-14">
                     Showing {(currentPage - 1) * doctorsPerPage + 1} –{" "}
{Math.min(currentPage * doctorsPerPage, totalDoctors)} of{" "}
{totalDoctors}
                    </span>
                  </div>
                  <nav aria-label="Doctor pagination">
                    <ul className="pagination justify-content-center mt-0">
                      {renderPagination()}
                    </ul>
                  </nav>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <style>
        {`
          /* Premium Toggle Switch Styles */
          .switch {
            position: relative;
            display: inline-block;
            width: 44px;
            height: 22px;
          }
          .switch input {
            opacity: 0;
            width: 0;
            height: 0;
          }
          .slider {
            position: absolute;
            cursor: pointer;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: #ccc;
            transition: .3s;
          }
          .slider:before {
            position: absolute;
            content: "";
            height: 16px;
            width: 16px;
            left: 3px;
            bottom: 3px;
            background-color: white;
            transition: .3s;
          }
          input:checked + .slider {
            background-color: #4caf50;
          }
          input:focus + .slider {
            box-shadow: 0 0 1px #4caf50;
          }
          input:checked + .slider:before {
            transform: translateX(22px);
          }
          .slider.round {
            border-radius: 22px;
          }
          .slider.round:before {
            border-radius: 50%;
          }

          .doctor-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 15px;
            margin-bottom: 20px;
          }

          .doctor-actions {
            display: flex;
            gap: 15px;
            align-items: center;
          }

          .doctor-search-input {
            max-width: 255px;
          }

          .add-doctor-btn {
            background-color: green;
            color: whitesmoke;
            padding: 10px 15px;
            border-radius: 5px;
            font-weight: 600;
            border: none;
            cursor: pointer;
            white-space: nowrap;
          }

          .doctor-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            object-fit: cover;
          }

          .edit-btn {
            background-color: #007bff;
            color: white;
            border: none;
            border-radius: 4px;
            padding: 5px 10px;
            margin-right: 5px;
            cursor: pointer;
          }

          /* Mobile Responsive Styles */
          @media (max-width: 667px) {
            .doctor-header {
              flex-direction: column;
              align-items: flex-start;
              gap: 15px;
            }

            .doctor-title {
              text-align: center;
              margin-bottom: 0;
              order: 1;
            }

            .doctor-actions {
              flex-direction: column;
              gap: 10px;
              width: 100%;
              order: 2;
            }

            .doctor-search-input {
              max-width: 100% !important;
              width: 100%;
              order: 2;
            }

            .add-doctor-btn {
              width: 100%;
              padding: 12px;
              order: 3;
            }
          }

          /* Small mobile devices */
          @media (max-width: 480px) {
            .doctor-header {
              gap: 10px;
            }

            .table-responsive {
              font-size: 12px;
            }

            .doctor-avatar {
              width: 40px;
              height: 40px;
            }

            .edit-btn {
              padding: 4px 8px;
              font-size: 12px;
            }

            .page-link {
              padding: 6px 10px;
              font-size: 12px;
            }
          }

          /* Premium Confirmation Modal Styles */
          .custom-modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 4, 36, 0.45);
            backdrop-filter: blur(8px);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 99999;
            animation: fadeIn 0.25s ease;
          }

          .custom-modal-container {
            background: #ffffff;
            border-radius: 16px;
            width: 90%;
            max-width: 500px;
            padding: 30px;
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
            border: 1px solid rgba(0, 0, 0, 0.05);
            transform: translateY(0);
            animation: slideUp 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
          }

          @keyframes fadeIn {
            from { opacity: 0; }
            to { opacity: 1; }
          }

          @keyframes slideUp {
            from { transform: translateY(20px); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
          }

          .modal-warning-header {
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
            margin-bottom: 24px;
          }

          .warning-icon-wrapper {
            width: 60px;
            height: 60px;
            border-radius: 50%;
            background-color: #fff3cd;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 16px;
            color: #ffc107;
            font-size: 30px;
            animation: pulse 2s infinite;
          }

          @keyframes pulse {
            0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(255, 193, 7, 0.4); }
            70% { transform: scale(1.05); box-shadow: 0 0 0 10px rgba(255, 193, 7, 0); }
            100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(255, 193, 7, 0); }
          }

          .modal-title-custom {
            font-size: 20px;
            font-weight: 700;
            color: #0c1a30;
            margin-bottom: 8px;
          }

          .modal-desc-custom {
            font-size: 14px;
            color: #5e6e82;
            line-height: 1.5;
          }

          .doctor-info-preview {
            display: flex;
            align-items: center;
            gap: 12px;
            background-color: #f8f9fa;
            padding: 12px;
            border-radius: 10px;
            margin-bottom: 20px;
            border-left: 4px solid #ffc107;
          }

          .doctor-preview-avatar {
            width: 45px;
            height: 45px;
            border-radius: 50%;
            object-fit: cover;
          }

          .doctor-preview-details h5 {
            font-size: 14px;
            font-weight: 600;
            margin: 0 0 2px 0;
            color: #0c1a30;
          }

          .doctor-preview-details p {
            font-size: 12px;
            color: #5e6e82;
            margin: 0;
          }

          .services-list-container {
            max-height: 160px;
            overflow-y: auto;
            background-color: #fafbfe;
            border: 1px solid #e2e8f0;
            border-radius: 10px;
            padding: 15px;
            margin-bottom: 24px;
          }

          .services-list-title {
            font-size: 12px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: #a0aec0;
            margin-bottom: 10px;
            font-weight: 700;
            text-align: left;
          }

          .services-list-items {
            list-style: none;
            padding: 0;
            margin: 0;
            text-align: left;
          }

          .services-list-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 13px;
            color: #334155;
            padding: 8px 0;
            border-bottom: 1px dashed #e2e8f0;
          }

          .services-list-item:last-child {
            border-bottom: none;
          }

          .service-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background-color: #ff4d4f;
            display: inline-block;
          }

          .modal-actions-custom {
            display: flex;
            gap: 12px;
            justify-content: flex-end;
          }

          .modal-btn {
            padding: 10px 20px;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s ease;
            border: none;
          }

          .modal-btn-cancel {
            background-color: #f1f5f9;
            color: #475569;
          }

          .modal-btn-cancel:hover {
            background-color: #e2e8f0;
          }

          .modal-btn-confirm {
            background-color: #ff4d4f;
            color: #ffffff;
            box-shadow: 0 4px 12px rgba(255, 77, 79, 0.2);
          }

          .modal-btn-confirm:hover {
            background-color: #e02424;
          }

          .modal-spinner {
            display: inline-block;
            width: 20px;
            height: 20px;
            border: 2px solid rgba(0, 0, 0, 0.1);
            border-radius: 50%;
            border-top-color: #007bff;
            animation: spin 1s ease-in-out infinite;
          }

          @keyframes spin {
            to { transform: rotate(360deg); }
          }
        `}
      </style>

      {showModal && selectedDoctorForToggle && (
        <div className="custom-modal-overlay" onClick={handleCancelDeactivate}>
          <div className="custom-modal-container" onClick={(e) => e.stopPropagation()}>
            <div className="modal-warning-header">
              <div className="warning-icon-wrapper">⚠️</div>
              <h3 className="modal-title-custom">Confirm Deactivation</h3>
              <p className="modal-desc-custom">
                Are you sure you want to make this doctor inactive? This action will hide all their related services on the website for users.
              </p>
            </div>

            <div className="doctor-info-preview">
              <img
                src={selectedDoctorForToggle.profilePhoto}
                alt={selectedDoctorForToggle.name}
                className="doctor-preview-avatar"
              />
              <div className="doctor-preview-details">
                <h5>{selectedDoctorForToggle.name}</h5>
                <p>{selectedDoctorForToggle.specialization}</p>
              </div>
            </div>

            <div className="services-list-container">
              <div className="services-list-title">
                {modalLoading ? "Loading affected services..." : `Affected Services (${relatedServices.length})`}
              </div>
              {modalLoading ? (
                <div style={{ display: 'flex', justifyContent: 'center', padding: '20px 0' }}>
                  <div className="modal-spinner"></div>
                </div>
              ) : relatedServices.length > 0 ? (
                <ul className="services-list-items">
                  {relatedServices.map((service) => (
                    <li key={service._id} className="services-list-item">
                      <span className="service-dot"></span>
                      <span>{service.serviceName}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <div style={{ fontSize: '13px', color: '#5e6e82', fontStyle: 'italic', textAlign: 'center', padding: '10px 0' }}>
                  No active services are currently associated with this doctor.
                </div>
              )}
            </div>

            <div className="modal-actions-custom">
              <button className="modal-btn modal-btn-cancel" onClick={handleCancelDeactivate}>
                Cancel
              </button>
              <button 
                className="modal-btn modal-btn-confirm" 
                onClick={handleConfirmDeactivate}
                disabled={modalLoading}
              >
                Confirm Deactivate
              </button>
            </div>
          </div>
        </div>
      )}

      <ToastContainer position="top-right" autoClose={3000} />
    </div>
  );
};

export default DashboardDoctors;